/* What the core exports: libretro's own functions and the probe patch's. Everything else is local to the library.
   Without this the library exports a copy of every C++ standard-library template it uses, libstdc++ binds to
   those copies, and the system then never unloads the library: each machine leaves its 42 MB of static memory
   behind for as long as the process lives. */
{
  global:
    retro_*;
    vblank_*;
  local:
    *;
};
